begin;
create extension if not exists pgtap with schema extensions;
select plan(15);
set local role authenticated;
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000001","role":"authenticated"}';
select is((select count(*)::int from public.businesses),1,'broker sees one business');
select is((select count(*)::int from public.leads),2,'broker sees only broker leads');
select is((select count(*)::int from public.businesses where id='10000000-0000-4000-8000-000000000002'),0,'cross-tenant business hidden');
select is((select count(*)::int from public.leads where business_id='10000000-0000-4000-8000-000000000002'),0,'cross-tenant leads hidden');
select throws_ok($$select public.manage_member('10000000-0000-4000-8000-000000000002','broker@example.test','admin')$$,'42501','Owner access required','cross-business team mutation denied');
select throws_ok($$select public.manage_member('10000000-0000-4000-8000-000000000001','broker@example.test','viewer')$$,'P0001','Owner cannot be modified','owner invariant protected');
select is(public.is_super_admin(),false,'owner is not platform administrator');
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000002","role":"authenticated"}';
select is((select count(*)::int from public.leads),1,'gym sees one gym lead');
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000004","role":"authenticated"}';
select is(public.has_role('10000000-0000-4000-8000-000000000001',array['owner','admin']),false,'viewer has no configuration privileges');
select throws_ok($$select public.manage_member('10000000-0000-4000-8000-000000000001','viewer@example.test','admin')$$,'42501','Owner access required','viewer cannot self-promote');
with changed as (update public.businesses set name='Hacked' where id='10000000-0000-4000-8000-000000000001' returning id) select is(count(*)::int,0,'viewer cannot update settings') from changed;
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000003","role":"authenticated"}';
select is(public.is_super_admin(),true,'platform admin recognized');
select is((select count(*)::int from public.businesses),2,'platform admin sees registry');
select is((select count(*)::int from public.leads),0,'platform admin cannot read tenant CRM');
reset role;
select is((select count(*)::int from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('businesses','memberships','contacts','conversations','messages','leads','knowledge_documents','ai_settings','style_profiles','chat_imports','appointments','whatsapp_accounts','usage_records') and c.relrowsecurity),13,'all thirteen tenant tables have RLS');
select * from finish();
rollback;
